<?php get_header(); while(have_posts()){the_post();$id=get_the_ID(); ?><div class="cg-article-layout"><article class="cg-page cg-narrow"><p class="cg-eyebrow">编辑内容</p><h1><?php the_title(); ?></h1><p class="cg-meta">作者：<?php the_author(); ?> · 更新：<?php echo esc_html(get_the_modified_date('Y-m-d')); ?><?php $date=get_post_meta($id,'_cg_reviewed',true);if($date){echo ' · 核验：'.esc_html($date);} ?></p><?php if(get_post_meta($id,'_cg_sponsored',true)){?><p class="cg-notice">赞助内容：本文涉及商业合作。</p><?php } ?><div class="cg-content"><?php the_content(); ?></div><?php $source=get_post_meta($id,'_cg_source',true);if($source){?><h2>主要资料来源</h2><a href="<?php echo esc_url($source,array('https')); ?>" rel="noopener noreferrer">查看来源 ↗</a><?php } ?></article><?php get_sidebar(); ?></div><?php } get_footer(); ?>
